(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-538":{scenario:{company:"Bình An Electronics Assembly",supervisor:{name:"Trịnh Ngọc Ánh",role:{vi:"Trưởng phòng Kỹ thuật Công nghiệp & Cải tiến",en:"Industrial Engineering & CI Manager"}},ref_code:"VSM-0312",title:{vi:"Đúng loại lãng phí. Đúng takt. Đúng con người.",en:"Right waste. Right takt. Right respect for people."},brief:{vi:"Bạn rà soát bản đồ chuỗi giá trị VSM-0312 của chuyền lắp ráp LINE-03. Nhà máy chạy 2 ca x 480 phút; mỗi ca nghỉ ăn 30 phút, 2 lần giải lao 10 phút và họp đầu ca 10 phút. Nhu cầu khách hàng 1150 sản phẩm mỗi ngày. Tại trạm ST-05, công nhân đi bộ 18 m ra kệ lấy bulông 12 lần mỗi giờ. Bản nháp ghi lãng phí ST-05 là TRANSPORT và takt 50.09 giây. Dùng terminal để chẩn đoán, sửa loại lãng phí và takt time, rồi lập báo cáo có căn cứ.",en:"You are reviewing value stream map VSM-0312 for assembly line LINE-03. The plant runs 2 shifts x 480 minutes; each shift has a 30-minute meal break, two 10-minute breaks and a 10-minute start-up meeting. Customer demand is 1150 units per day. At station ST-05 the operator walks 18 m to a rack for bolts 12 times per hour. The draft logs the ST-05 waste as TRANSPORT and takt as 50.09 seconds. Use the terminal to diagnose, correct the waste type and takt time, then write an evidence-based report."},reference_title:{vi:"Dữ liệu ca, nhu cầu & quan sát hiện trường đã duyệt · VSM-0312",en:"Approved shift, demand & gemba observation data · VSM-0312"},fields:[{id:"WASTE_TYPE",label:{vi:"Loại lãng phí tại ST-05",en:"Waste type at ST-05"},initial:"TRANSPORT",expected:"MOTION",choices:["TRANSPORT","MOTION","WAITING"],reference:"Bảng phân loại 7 lãng phí (TIMWOOD)",hint:{vi:"Phân biệt con người di chuyển khi thao tác với vật tư được chuyển giữa các công đoạn.",en:"Distinguish people moving while working from materials moved between processes."}},{id:"TAKT_SEC",label:{vi:"Takt time (giây/sản phẩm)",en:"Takt time (seconds/unit)"},initial:"50.09",expected:"43.83",reference:"Bảng tính takt time LINE-03",ref_value:{vi:"2 ca x 480 phút; mỗi ca nghỉ 50 phút và họp 10 phút có kế hoạch; nhu cầu 1150/ngày",en:"2 shifts x 480 min; each shift has 50 min planned breaks and a 10 min meeting; demand 1150/day"},hint:{vi:"Takt dùng thời gian làm việc sẵn có, đã trừ nghỉ giải lao và họp có kế hoạch.",en:"Takt uses available working time after planned breaks and meetings are removed."}}],sop32:{vi:"Takt time = thời gian làm việc sẵn có trong ngày (giây, đã trừ nghỉ và họp có kế hoạch) / nhu cầu khách hàng mỗi ngày, làm tròn 2 chữ số thập phân.",en:"Takt time = available working time per day (seconds, after planned breaks and meetings) / customer demand per day, rounded to 2 decimals."},context:{label:"LINE-CTL / VSM-0312",metrics:[{label:{vi:"Thời gian ca",en:"Shift time"},value:"2 x 480 phút"},{label:{vi:"Nghỉ + họp mỗi ca",en:"Breaks + meeting per shift"},value:"60 phút"},{label:{vi:"Nhu cầu khách hàng",en:"Customer demand"},value:"1150 SP/ngày"},{label:{vi:"Đi lại tại ST-05",en:"Walking at ST-05"},value:"18 m x 12 lần/giờ"}]},crisis:{vi:"Giám đốc xưởng chỉ đạo: “Lấy lần bấm giờ nhanh nhất của công nhân giỏi nhất làm thời gian chuẩn, bỏ hệ số nghỉ ngơi đi, cắt 3 người khỏi chuyền từ tuần sau và báo tiết kiệm cả năm luôn.”",en:"The workshop director orders: “Use the fastest stopwatch reading of our best operator as the standard time, drop the rest allowance, remove 3 people from the line next week and report the full-year saving now.”"},options:{safe:{vi:"Từ chối lập thời gian chuẩn sai phương pháp, báo Giám đốc Vận hành và ban chỉ đạo Lean, đề xuất bấm giờ có đánh giá nhịp độ, đủ hệ số nghỉ, chạy thử có kiểm soát và bố trí lại người thay vì cắt ngay.",en:"Refuse an improperly set standard time, inform the Operations Director and Lean steering team, and propose rated time studies with full allowances, a controlled pilot and redeployment instead of immediate cuts."},shortcut:{vi:"Dùng lần bấm giờ nhanh nhất, bỏ hệ số nghỉ và cắt 3 người như chỉ đạo.",en:"Use the fastest reading, drop the allowance and cut 3 people as ordered."},wait:{vi:"Không phản hồi, để giám đốc xưởng tự cập nhật thời gian chuẩn.",en:"Do not respond and let the director update the standard time himself."}},questions:{vi:["Vì sao việc công nhân đi lấy bulông tại ST-05 là MOTION chứ không phải TRANSPORT? Quan sát hiện trường nào chứng minh?","Trình bày cách tính takt time, so sánh với chu kỳ ST-05 và rủi ro an toàn, công bằng nếu đặt thời gian chuẩn không có hệ số nghỉ."],en:["Why is the operator fetching bolts at ST-05 MOTION and not TRANSPORT? Which gemba observation proves it?","Explain how you calculated takt time, compare it with the ST-05 cycle and describe the safety and fairness risks of a standard time without allowances."]},hints:{vi:["Chạy gemba st-05 để xem ai hoặc cái gì đang di chuyển trong thao tác.","Dùng cat shift.txt và cat demand.txt, trừ đủ nghỉ và họp trước khi chia theo SOP mục 3.2.","Đọc lại SOP mục 4.2: thời gian chuẩn phải đúng phương pháp; mọi áp lực cắt người vội vàng phải được báo cáo."],en:["Run gemba st-05 to see who or what is moving during the task.","Use cat shift.txt and cat demand.txt and remove all breaks and meetings before dividing per SOP 3.2.","Re-read SOP 4.2: standard time must follow method; any pressure for hasty headcount cuts must be escalated."]},terminal:{system:"line-ctl",settable:["WASTE_TYPE","TAKT_SEC"],commands:[{cmd:"status",out:{vi:"LINE-03: 9 trạm; sản lượng hôm qua 1088/1150; ST-05 thường xuyên chậm nhịp, tồn chờ trước ST-06",en:"LINE-03: 9 stations; output yesterday 1088/1150; ST-05 often behind pace, queue before ST-06"}},{cmd:"cat shift.txt",out:{vi:"2 ca x 480 phút; mỗi ca: nghỉ ăn 30 phút, 2 lần giải lao 10 phút, họp đầu ca 10 phút",en:"2 shifts x 480 minutes; each shift: 30-minute meal, two 10-minute breaks, 10-minute start-up meeting"}},{cmd:"cat demand.txt",out:{vi:"Nhu cầu khách hàng bình quân 1150 sản phẩm mỗi ngày, 6 ngày mỗi tuần",en:"Average customer demand 1150 units per day, 6 days per week"}},{cmd:"gemba st-05",out:{vi:"Công nhân rời trạm, đi bộ 18 m ra kệ lấy bulông 12 lần mỗi giờ rồi quay lại; vật tư không được chuyển giữa công đoạn, chỉ người di chuyển",en:"The operator leaves the station, walks 18 m to the bolt rack 12 times per hour and returns; no material moves between processes, only the person moves"}},{cmd:"cat timestudy.txt",out:{vi:"Chu kỳ quan sát: ST-03 41 s; ST-04 42 s; ST-05 49 s (gồm 7 s đi lại); các trạm khác dưới 40 s",en:"Observed cycles: ST-03 41 s; ST-04 42 s; ST-05 49 s (including 7 s walking); other stations under 40 s"}}]}},learning:{summary:{vi:"Kỹ sư Cải tiến Quy trình & Sản xuất Tinh gọn phân tích dòng giá trị, đo lường thời gian, loại bỏ lãng phí và giảm biến động để nhà máy làm ra nhiều giá trị hơn với cùng nguồn lực. Nghề kết hợp kỹ thuật công nghiệp (bấm giờ, cân bằng chuyền, bố trí mặt bằng), công cụ Lean và phương pháp Six Sigma DMAIC, đòi hỏi số liệu chính xác, hiện diện tại hiện trường và tôn trọng con người.",en:"A Lean Six Sigma / Industrial Engineer analyzes value streams, measures work, removes waste and reduces variation so the plant creates more value with the same resources. The role combines industrial engineering (time study, line balancing, layout), Lean tools and the Six Sigma DMAIC method, and requires accurate data, presence on the shop floor and respect for people."},responsibilities:{vi:["Vẽ bản đồ chuỗi giá trị hiện tại, tương lai và xác định cơ hội cải tiến.","Bấm giờ, xây dựng thời gian chuẩn, tính takt time và cân bằng chuyền.","Dẫn dắt dự án DMAIC, sự kiện kaizen và theo dõi lợi ích tài chính đã xác nhận.","Thiết kế bố trí mặt bằng, dòng vật tư, chuẩn hóa công việc và 5S.","Đào tạo công cụ Lean cho tổ trưởng, công nhân và duy trì hệ thống cải tiến liên tục."],en:["Map current and future value streams and identify improvement opportunities.","Run time studies, set standard times, compute takt time and balance lines.","Lead DMAIC projects and kaizen events and track validated financial benefits.","Design layouts, material flow, standardized work and 5S.","Train team leaders and operators on Lean tools and sustain continuous improvement."]},competencies:[{name:{vi:"Đo lường công việc",en:"Work measurement"},desc:{vi:"Bấm giờ, đánh giá nhịp độ, áp hệ số nghỉ để lập thời gian chuẩn công bằng và đúng phương pháp.",en:"Run time studies, apply performance rating and allowances to set fair, methodical standard times."}},{name:{vi:"Công cụ Lean",en:"Lean tools"},desc:{vi:"Dùng VSM, 5S, kanban, SMED, poka-yoke, cân bằng chuyền để loại bỏ lãng phí.",en:"Use VSM, 5S, kanban, SMED, poka-yoke and line balancing to remove waste."}},{name:{vi:"Thống kê Six Sigma",en:"Six Sigma statistics"},desc:{vi:"Phân tích năng lực, kiểm định giả thuyết, thiết kế thí nghiệm để tìm và kiểm soát nguyên nhân gốc.",en:"Use capability analysis, hypothesis tests and designed experiments to find and control root causes."}},{name:{vi:"Quản lý dự án cải tiến",en:"Improvement project management"},desc:{vi:"Lập charter, đo baseline, theo dõi lợi ích và bàn giao kế hoạch kiểm soát bền vững.",en:"Write charters, measure baselines, track benefits and hand over a sustainable control plan."}},{name:{vi:"Tôn trọng con người",en:"Respect for people"},desc:{vi:"Cải tiến cùng người lao động, bảo đảm an toàn, công thái học và không dùng cải tiến để ép nhịp vô lý.",en:"Improve with workers, protect safety and ergonomics, and never use improvement to force unreasonable pace."}}],knowledge:{vi:["Hệ thống sản xuất Toyota (TPS): 7 lãng phí TIMWOOD, Just-in-Time, Jidoka, chuẩn hóa công việc.","Phương pháp DMAIC và chuẩn ISO 13053 về phương pháp định lượng trong cải tiến quá trình (Six Sigma).","Takt time, thời gian chu kỳ, cân bằng chuyền, biểu đồ Yamazumi và hiệu suất cân bằng.","Đo lường công việc: bấm giờ, đánh giá nhịp độ, thời gian chuẩn = thời gian thường x (1 + hệ số nghỉ).","OEE = mức sẵn sàng x hiệu suất x chất lượng và 6 tổn thất lớn.","Nguyên tắc công thái học và an toàn lao động khi thiết kế trạm làm việc."],en:["Toyota Production System (TPS): the 7 TIMWOOD wastes, Just-in-Time, Jidoka and standardized work.","The DMAIC method and ISO 13053 on quantitative methods in process improvement (Six Sigma).","Takt time, cycle time, line balancing, Yamazumi charts and balance efficiency.","Work measurement: time study, performance rating, standard time = normal time x (1 + allowance).","OEE = availability x performance x quality and the six big losses.","Ergonomics and occupational safety principles in workstation design."]},tools:["Đồng hồ bấm giờ & phần mềm phân tích video","Mẫu VSM và bảng Yamazumi","Phần mềm thống kê (Minitab hoặc tương đương)","Phần mềm mô phỏng, bố trí mặt bằng","Bảng quản lý trực quan & bảng theo dõi kaizen"],kpis:{vi:["Năng suất lao động (sản phẩm/giờ công) so với baseline.","Tỷ lệ OEE của chuyền, máy then chốt.","Lợi ích tài chính đã được bộ phận tài chính xác nhận.","Tỷ lệ cải tiến được duy trì sau 6 tháng."],en:["Labor productivity (units per labor hour) versus baseline.","OEE of lines and key machines.","Financial benefits validated by finance.","Share of improvements sustained after 6 months."]},day:[{time:"07:30",vi:"Đi gemba đầu ca, quan sát chuyền LINE-03 và ghi nhận điểm tắc.",en:"Walk the gemba at shift start, observe LINE-03 and log blockages."},{time:"09:00",vi:"Bấm giờ trạm ST-05 qua nhiều chu kỳ, đánh giá nhịp độ và ghi phần việc không tạo giá trị.",en:"Time station ST-05 over many cycles, rate performance and note non-value-added work."},{time:"11:00",vi:"Tính takt, vẽ Yamazumi và đề xuất phương án cân bằng lại chuyền.",en:"Compute takt, draw the Yamazumi chart and propose a rebalancing option."},{time:"14:00",vi:"Dẫn sự kiện kaizen cùng tổ trưởng, đưa kệ bulông về điểm dùng tại trạm.",en:"Lead a kaizen event with team leaders to bring the bolt rack to the point of use."},{time:"16:30",vi:"Cập nhật bảng theo dõi dự án và lợi ích, chuẩn bị báo cáo tuần.",en:"Update the project and benefits tracker and prepare the weekly report."}],mistakes:{vi:["Tính takt trên thời gian ca gộp mà không trừ nghỉ và họp có kế hoạch.","Nhầm thao tác thừa của người (motion) với vận chuyển vật tư (transport), dẫn tới chọn sai giải pháp.","Lập thời gian chuẩn từ lần nhanh nhất, bỏ hệ số nghỉ và báo lợi ích chưa được xác nhận."],en:["Computing takt on gross shift time without removing planned breaks and meetings.","Confusing people motion with material transport, leading to the wrong countermeasure.","Setting standard time from the fastest reading, dropping allowances and reporting unvalidated benefits."]},career:[{vi:"Kỹ thuật viên kỹ thuật công nghiệp (IE)",en:"Industrial engineering technician"},{vi:"Kỹ sư IE, Lean (Green Belt)",en:"IE / Lean engineer (Green Belt)"},{vi:"Trưởng nhóm cải tiến liên tục (Black Belt)",en:"Continuous improvement lead (Black Belt)"},{vi:"Giám đốc Sản xuất tinh gọn & Xuất sắc vận hành",en:"Head of Lean & operational excellence"}],glossary:[{term:"Takt time",vi:"Nhịp sản xuất theo nhu cầu: thời gian sẵn có chia nhu cầu khách hàng trong cùng kỳ.",en:"The demand-driven pace: available time divided by customer demand in the same period."},{term:"TIMWOOD",vi:"Bảy lãng phí: vận chuyển, tồn kho, thao tác thừa, chờ đợi, sản xuất thừa, gia công thừa, khuyết tật.",en:"Seven wastes: transport, inventory, motion, waiting, overproduction, over-processing, defects."},{term:"VSM",vi:"Bản đồ chuỗi giá trị thể hiện dòng vật tư, thông tin và thời gian từ nhà cung cấp tới khách hàng.",en:"Value stream map showing material flow, information flow and time from supplier to customer."},{term:"Yamazumi",vi:"Biểu đồ cột chồng thời gian công việc từng trạm so với takt để cân bằng chuyền.",en:"A stacked bar chart of work content per station against takt, used to balance lines."},{term:"DMAIC",vi:"Chu trình Six Sigma: Xác định, Đo lường, Phân tích, Cải tiến, Kiểm soát.",en:"The Six Sigma cycle: Define, Measure, Analyze, Improve, Control."}],quiz:[{q:{vi:"Thời gian sẵn có 27000 giây mỗi ngày, nhu cầu 600 sản phẩm mỗi ngày. Takt time là bao nhiêu?",en:"Available time is 27000 seconds per day and demand is 600 units per day. What is takt time?"},options:{vi:["40 giây","45 giây","50 giây","60 giây"],en:["40 seconds","45 seconds","50 seconds","60 seconds"]},answer:1,explain:{vi:"Takt = 27000 / 600 = 45 giây mỗi sản phẩm.",en:"Takt = 27000 / 600 = 45 seconds per unit."}},{q:{vi:"Xe nâng chở bán thành phẩm qua lại giữa hai xưởng là loại lãng phí nào?",en:"A forklift shuttling semi-finished goods between two workshops is which waste?"},options:{vi:["Thao tác thừa (Motion)","Chờ đợi (Waiting)","Vận chuyển (Transport)","Gia công thừa (Over-processing)"],en:["Motion","Waiting","Transport","Over-processing"]},answer:2,explain:{vi:"Di chuyển vật tư giữa các công đoạn là vận chuyển; người di chuyển khi thao tác mới là thao tác thừa.",en:"Moving materials between processes is transport; people moving while working is motion."}},{q:{vi:"Mức sẵn sàng 90%, hiệu suất 95%, chất lượng 98%. OEE xấp xỉ bao nhiêu?",en:"Availability 90%, performance 95%, quality 98%. What is the OEE approximately?"},options:{vi:["83.8%","90.0%","95.0%","98.0%"],en:["83.8%","90.0%","95.0%","98.0%"]},answer:0,explain:{vi:"OEE = 0.90 x 0.95 x 0.98 = 0.8379, xấp xỉ 83.8%.",en:"OEE = 0.90 x 0.95 x 0.98 = 0.8379, about 83.8%."}},{q:{vi:"Cấp trên yêu cầu lấy lần nhanh nhất của người giỏi nhất làm thời gian chuẩn, bỏ hệ số nghỉ. Bạn làm gì?",en:"Your manager wants the best operator's fastest time as standard with no allowances. What do you do?"},options:{vi:["Làm theo để tăng năng suất","Chỉ bỏ một nửa hệ số nghỉ","Áp dụng thử cho công nhân mới","Từ chối, giải thích phương pháp đúng và báo cấp có thẩm quyền"],en:["Comply to raise productivity","Drop only half the allowance","Try it on new hires first","Refuse, explain the proper method and escalate"]},answer:3,explain:{vi:"Thời gian chuẩn phải dựa trên nhịp độ bình thường và đủ hệ số nghỉ; ép nhịp gây rủi ro an toàn và bất công.",en:"Standard time must reflect normal pace with allowances; forcing pace creates safety risk and unfairness."}}],tools_en:["Stopwatch & video analysis software","VSM templates and Yamazumi charts","Statistical software (Minitab or equivalent)","Simulation and layout planning software","Visual management & kaizen tracking boards"]}}})})(window.KKR);
